<template><div class="auth-page"><div class="auth-glow"></div><div class="auth-card"><div class="auth-brand"><span>◈</span> UAV<span>·VISION</span></div><div class="auth-kicker">REMOTE INTELLIGENCE PLATFORM</div><h1>欢迎回来</h1><p>登录平台，继续管理你的遥感解译任务</p><el-form :model="form" @submit.prevent="submit"><el-form-item><el-input v-model="form.account" size="large" placeholder="用户名或邮箱" :prefix-icon="User"/></el-form-item><el-form-item><el-input v-model="form.password" size="large" type="password" show-password placeholder="密码" :prefix-icon="Lock" @keyup.enter="submit"/></el-form-item><el-button class="auth-submit" size="large" type="primary" :loading="loading" @click="submit">登录平台</el-button></el-form><div class="auth-switch">还没有账号？<el-link type="primary" @click="$router.push('/register')">立即注册</el-link></div><div class="auth-foot">SECURE SESSION · AI OPERATIONS CENTER</div></div></div></template>
<script setup>import{ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{User,Lock}from'@element-plus/icons-vue';import{authApi}from'../api/http';const router=useRouter(),loading=ref(false),form=ref({account:'',password:''});async function submit(){if(!form.value.account||!form.value.password)return ElMessage.warning('请输入账号和密码');loading.value=true;try{await authApi.login(form.value);ElMessage.success('登录成功');router.push('/dashboard')}catch(e){ElMessage.error(e.response?.data?.message||'登录失败，请检查账号密码')}finally{loading.value=false}}</script>
